  function el(tag,cls,text){const node=document.createElement(tag);if(cls)node.className=cls;if(text!==undefined)node.textContent=text;return node;}
  function button(text,cls,action){const node=el('button',cls,text);node.type='button';node.addEventListener('click',action);return node;}
  function sprite(index){const frame=el('span','sprite');const img=el('img');img.src='assets/students-'+art+'.png';img.alt='';frame.style.setProperty('--cropx',(-[200,620,1080][index%3]/300*100)+'%');frame.style.setProperty('--cropy',index<3?'0%':'-100%');frame.append(img);return frame;}
