  function renderClues(){const s=session(),c=current();$('clues').replaceChildren();$('sceneTools').replaceChildren();c.required.forEach((key,index)=>{const earned=s.earned.includes(key),pinned=s.pinned.includes(key);const card=el('article','clue-card');const cover=el('div','clue-cover',mode==='photo'?['☾','▰','↔'][index]:['⌁','◷','◇'][index]);cover.setAttribute('aria-hidden','true');const content=el('div','clue-card-content');content.append(el('h4','',clueLabel(key)),el('p','',clueSummary(key)));const controls=el('div','clue-buttons');controls.append(button(earned?'Xem nguồn':'Khám xét','small-btn',()=>challenge(key)));if(earned){const pin=button(pinned?'✓ Đã ghim':'Ghim nguồn','small-btn'+(pinned?' pinned':''),()=>{const ix=s.pinned.indexOf(key);if(ix>=0)s.pinned.splice(ix,1);else s.pinned.push(key);renderClues();renderTrial();});pin.setAttribute('aria-pressed',String(pinned));pin.dataset.pin=key;controls.append(pin);}content.append(controls);card.append(cover,content);$('clues').append(card);
      const hot=button((earned?'✓ ':'⌕ ')+clueLabel(key),'scene-tool'+(earned?' earned':''),()=>challenge(key));hot.style.left=([10,68,42][index])+'%';hot.style.top=([30,36,51][index])+'%';hot.dataset.clue=key;$('sceneTools').append(hot);
    });$('evidenceCount').textContent=s.earned.length+'/'+c.required.length+' nguồn · '+s.pinned.length+' đã ghim';}
  function renderLevels(){const track=$('levels');track.replaceChildren();M[mode].forEach((c,i)=>{const done=progress[mode].completed.includes(i);const b=button('','level'+(level===i?' active':''),()=>{if(i>progress[mode].unlocked)return;level=i;render();});b.disabled=i>progress[mode].unlocked;b.dataset.level=String(i);b.append(el('b','',done?'✓':String(i+1)),el('span','',i===0?'Quan sát':i===1?(mode==='photo'?'Nối hai nguồn':'Ghé checkpoint'):(mode==='photo'?'Cân ba bảng':'Đợi cổng mở')));b.setAttribute('aria-label','Vụ '+(i+1)+': '+c.title+(b.disabled?', chưa mở':''));track.append(b);});}
  function renderTrial(){const c=current(),s=session(),target=$('trialResult');target.replaceChildren();$('suspect').value=s.selected;$('next').hidden=!s.solved||level===2;$('submit').disabled=s.solved;if(!s.selected){target.textContent='Chọn hồ sơ để thử. Thử không làm thay đổi nguồn thật.';return;}const result=M.trial(c,mode,s.selected,s.earned);if(result.status==='insufficient'){target.textContent='Còn thiếu nguồn về hành trình. Chưa kiểm tính khả thi hoặc chấm danh tính.';return;}if(mode==='photo'){if(!result.rows.length){target.textContent='Chưa kiếm được bảng đếm nào. Không tính theo nguồn chưa mở.';return;}for(const row of result.rows){const line=el('div','trial-line');line.append(el('span','',M.fields[row.key].name),el('b',row.matches?'yes':'no',row.matches?'✓ Khớp nguồn đã kiếm':'≠ Chưa khớp'));target.append(line);}if(s.earned.length<c.required.length)target.append(el('p','','Còn nguồn chưa mở. Dấu khớp hiện tại chưa phải kết luận.'));}else{target.append(el('div','trial-line','Cần ít nhất '+result.needed+' phút · Hồ sơ ghi '+result.available+' phút'),el('p','',result.needed>result.available?'Hành trình không khả thi theo những nguồn đã kiếm.':'Hành trình có thể xảy ra, kể cả khi có thời gian chờ.'));}}
  function render(){const c=current(),s=session();document.body.classList.toggle('pixel',art==='pixel');$('room').src='assets/classroom-'+art+'.png';$('scene').dataset.ceVariant='Sĩ số +1 · '+(art==='pixel'?'Pixel':'Hoạt hình');$('caseTitle').textContent='Vụ '+(level+1)+'/3 · '+c.title;$('caseIntro').textContent=c.intro;$('caseSkill').textContent=c.skill;$('stamp').textContent=c.stamp;$('rule').textContent=mode==='photo'?'Luật mô phỏng: ảnh đầy đủ xác nhận đồ của đúng 5 vai. Cả 5 hồ sơ thật khớp mọi bảng đếm, đúng 1 hồ sơ do máy ghép thừa. Các ảnh cận cùng mã nguồn, không có người bị che ngoài phạm vi đếm.':'Luật mô phỏng: 5 hồ sơ là hành trình hợp lệ, đúng 1 hồ sơ bị máy ghép sai hai lượt quét. Có thể chờ, không có lối tắt. Đây là bản ghi máy, không phải lời khai có thể nói dối.';document.querySelectorAll('[data-art]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.art===art)));document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===mode)));renderLevels();renderCharacters();renderProfiles();renderClues();renderTrial();$('feedback').textContent=s.solved?'Vụ này đã được giải từ đủ nguồn. Có thể xem lại hoặc mở vụ tiếp theo.':'';}
  function photoSource(container,key){const c=current(),field=M.fields[key];container.append(el('p','note',field.hint+' Các vật thể đã được tách khỏi định danh. Thứ tự vật giữa các ảnh cận không phải thứ tự người.'));const photo=el('div','photo-source');photo.append(el('span','source-stamp',c.stamp+' · ẢNH CẬN '+field.name.toUpperCase()+' · 5 VẬT'));const strip=el('div','strip');const values=[];c.proof[key].forEach((n,index)=>{for(let i=0;i<n;i++)values.push(index);});if(level>0)values.reverse();values.forEach((value,index)=>{const token=el('span','token'+(key==='book'?(value===0?' yellow':' blue'):''),field.icons[value]);token.style.setProperty('--rot',(index%2?4:-3)+'deg');token.setAttribute('aria-label',field.labels[value]);strip.append(token);});photo.append(strip);const lens=el('span','source-lens');lens.setAttribute('aria-hidden','true');photo.append(lens);container.append(photo);const label=el('label','','Di chuyển kính lúp, hoặc đọc nhãn từng vật bằng trình đọc màn hình.');label.style.fontSize='11px';const slider=el('input','lens-track');slider.type='range';slider.min='0';slider.max='100';slider.value='35';slider.setAttribute('aria-label','Vị trí kính lúp trên ảnh cận');slider.addEventListener('input',()=>{lens.style.left=(Number(slider.value)*.75+2)+'%';});label.append(slider);container.append(label);}
