  function routeSource(container,key){const c=current();if(key==='map'){mapSource(container);return;}if(key==='scan'){const table=el('table','scan-table'),head=el('thead');head.innerHTML='<tr><th>Hồ sơ</th><th>Quét đầu</th><th>Quét cuối</th><th>Khoảng cách giờ</th></tr>';const body=el('tbody');c.rows.forEach(row=>{const tr=el('tr');[M.profiles.find(p=>p.id===row.id).name,M.nodes[row.from],M.nodes[row.to],row.minutes+' phút'].forEach(v=>tr.append(el('td','',v)));body.append(tr);});table.append(head,body);container.append(table,el('p','note','Mỗi dòng là hai bản ghi cùng định danh hồ sơ. Khoảng cách giờ lấy từ fixture công khai, không suy từ tính cách. Ở vụ 3 mọi dòng bắt đầu 08:50.'));return;}if(key==='checkpoint'){mapSource(container);container.append(el('p','','Bản ghi xác nhận: cả năm hành trình thật đều phải qua P, phòng máy, giữa hai lượt quét. Nếu bắt đầu ở P, lượt quét đầu đã xác nhận checkpoint.'),el('p','note','Được đi qua cùng một khu nhiều lần. Đừng bỏ đoạn quay lại.'));return;}
    const clock=el('div','route-clock');const reading=el('span','clock-reading','08:50'),status=el('div','clock-status','Cổng nhận lượt khởi hành.');const slider=el('input');slider.type='range';slider.min='50';slider.max='58';slider.value='50';slider.step='1';slider.setAttribute('aria-label','Thử thời điểm khởi hành ở cổng');slider.addEventListener('input',()=>{const minute=Number(slider.value);reading.textContent='08:'+minute;status.textContent=minute>50&&minute<55?'Cổng không nhận lượt mới. Chờ tới 08:55.':'Cổng nhận lượt khởi hành. Qua cổng mất hai phút.';});clock.append(reading,status,slider);container.append(clock,el('p','','Lượt khởi hành 08:50 vẫn hoàn tất sau hai phút. Cổng ngừng nhận lượt mới 08:51–08:54 và mở lại 08:55. Lịch áp dụng hai chiều.'));}
  function challenge(key){const c=current(),s=session();if(!c.required.includes(key))return;open(clueLabel(key),c.stamp+' · NGUỒN HƯ CẤU ĐỂ KIẾM');const content=el('div','dialog-content');if(mode==='photo')photoSource(content,key);else routeSource(content,key);
    if(s.earned.includes(key)){content.append(el('p','counts','✓ Đã kiếm nguồn. '+clueSummary(key)),button(s.pinned.includes(key)?'Đã ghim, trở về bảng':'Ghim nguồn này','primary',()=>{if(!s.pinned.includes(key))s.pinned.push(key);close();renderClues();renderTrial();}));}else{const q=M.clueQuiz(c,mode,key),quiz=el('form','quiz'),label=el('label','',q.question),input=el('input');input.type='number';input.min=String(q.min);input.max=String(q.max);input.step='1';input.required=true;input.setAttribute('aria-label',q.question);input.dataset.quiz=key;const submit=el('button','primary','Xác nhận phép kiểm');submit.type='submit';const message=el('p','quiz-message');message.setAttribute('role','status');quiz.append(label,input,submit,message);quiz.addEventListener('submit',e=>{e.preventDefault();if(input.value===''||!Number.isInteger(Number(input.value))){message.textContent='Nhập một số nguyên từ nguồn đang xem.';return;}if(Number(input.value)!==q.answer){message.textContent='Chưa khớp phần nguồn đang xem. Kiểm lại, không mất lượt.';return;}if(!s.earned.includes(key))s.earned.push(key);if(!s.pinned.includes(key))s.pinned.push(key);close();renderClues();renderTrial();toast('Đã kiếm và ghim '+clueLabel(key)+'.');});content.append(quiz);} $('dialogBody').append(content);
  }
  function showTarot(){const c=current();open(level===0?'The Moon':level===1?'Justice':'Wheel of Fortune','LÁ GỢI CÁCH KIỂM · KHÔNG PHẢI BẰNG CHỨNG');const content=el('div','dialog-content tarot-layout'),card=el('div','tarot-card');const inner=el('div');inner.append(el('span','moon',level===0?'☾':level===1?'⚖':'☼'),el('small','',level===0?'THE MOON':level===1?'JUSTICE':'WHEEL OF FORTUNE'));card.append(inner);const copy=el('div');copy.append(el('h3','',mode==='photo'?'Nhìn lại phần đã kiểm chứng':'Đọc đường đi cùng mốc giờ'),el('p','',c.hint),el('p','note','Lá này không biết ai là hồ sơ thừa, không mở nguồn chưa kiếm và không dùng cung của nhân vật để suy ra đáp án.'));content.append(card,copy);$('dialogBody').append(content);}
