    content.append(el('p','note','Tính cách, cung và tarot không được dùng trong phép kiểm. Không có điểm kinh nghiệm, coin, streak hoặc dữ liệu gửi ra ngoài.'));if(level<2)content.append(button('Mở vụ '+(level+2)+' →','primary',next));else content.append(button(mode==='photo'?'Thử option hành trình →':'Quay lại option ảnh →','primary',()=>{mode=mode==='photo'?'route':'photo';level=0;close();render();}));$('dialogBody').append(content);
