  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('shade').hidden)close();if(e.key==='Tab'&&!$('shade').hidden){const list=[...$('modal').querySelectorAll('button:not(:disabled),input,select,a[href]')];if(!list.length)return;const first=list[0],last=list[list.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});render();
